previewCss:
.darma-loader-rocket-launch {
  position: relative;
  width: 34px;
  height: 52px;
  animation: darma-loader-rocket-launch-lift 1.6s ease-in-out infinite;
}
.darma-loader-rocket-launch::before {
  content: "";
  position: absolute;
  top: 0;
  left: 50%;
  width: 16px;
  height: 30px;
  margin-left: -8px;
  border-radius: 50% 50% 40% 40%;
  background: var(--loader-color, #6366f1);
  box-shadow: inset 0 0 0 3px #4338ca, inset 0 6px 0 -3px #e0e7ff;
}
.darma-loader-rocket-launch i {
  position: absolute;
  top: 30px;
  left: 50%;
  width: 10px;
  height: 14px;
  margin-left: -5px;
  background: #f59e0b;
  clip-path: polygon(0 0, 100% 0, 50% 100%);
  transform-origin: top center;
  animation: darma-loader-rocket-launch-flame 0.18s linear infinite alternate;
}
@keyframes darma-loader-rocket-launch-lift {
  0%, 100% { transform: translateY(4px); }
  50% { transform: translateY(-4px); }
}
@keyframes darma-loader-rocket-launch-flame {
  from { transform: scaleY(0.7); opacity: 0.8; }
  to { transform: scaleY(1.15); opacity: 1; }
}

